    // Inicialización en el primer frame
    if (!mc._fpsMaxLast) {
      mc._fpsMaxLast = now;
      mc._fpsAccum = 0;
    }

    const elapsed = now - mc._fpsMaxLast;
    mc._fpsMaxLast = now;

    // Evitar ráfagas tras pausar la pestaña (máximo 2 frames de deuda acumulada)
    mc._fpsAccum = Math.min(mc._fpsAccum + elapsed, per * 2);

